template:
use std::convert::TryFrom;

#[derive(Debug, PartialEq)]
struct Port(u16);

impl TryFrom<u32> for Port {
    type Error = &'static str;

    fn try_from(
        val: u32,
    ) -> Result<Self, Self::Error> {
        if val ⟦cmp⟧ 65535 {
            Ok(Port(val ⟦cast⟧))
        } else {
            Err("out of range")
        }
    }
}

fn main() {
    let p = Port::try_from(8080);
    assert_eq!(p, Ok(Port(8080)));
}
